import { Injectable } from '@angular/core';
import { APP_CONFIG } from '../config';
import { AyahRef } from '../models';

/**
 * Shape of `content/<edition>/arabic.json`, generated by scripts/build-content.mjs
 * (never hand-edited). Keys are "surah:ayah".
 */
export interface ArabicFile {
  format: 'mushaf-arabic';
  version: 1;
  source: { name: string; url: string; origin: string; license: string; fetchedAt: string };
  ayahs: Record<string, string>;
}

/**
 * Unicode Arabic text per ayah (Kemenag RI). Used ONLY for sharing/copying; the
 * mushaf page is always drawn from the artwork. Loaded lazily on first use
 * (~1.4 MB) and cached by the service worker for offline use afterwards.
 */
@Injectable({ providedIn: 'root' })
export class ArabicTextService {
  private file: Promise<ArabicFile | null> | null = null;
  /** Synchronous view once loaded. */
  private loaded: ArabicFile | null = null;

  /** Resolves to the Arabic text, or null when unavailable (offline before first load, missing file). */
  async get(ref: AyahRef): Promise<string | null> {
    const f = await this.load();
    return f?.ayahs[`${ref.surah}:${ref.ayah}`] ?? null;
  }

  /** Starts loading in the background (e.g. when the verse sheet opens) so sharing is instant. */
  preload(): void {
    void this.load();
  }

  /** Text if the file is already in memory, else null (no network). */
  peek(ref: AyahRef): string | null {
    return this.loaded?.ayahs[`${ref.surah}:${ref.ayah}`] ?? null;
  }

  private load(): Promise<ArabicFile | null> {
    this.file ??= fetch(`${APP_CONFIG.contentBase}/${APP_CONFIG.editionId}/arabic.json`)
      .then(async (r) => {
        if (!r.ok) throw new Error(String(r.status));
        const f = (await r.json()) as ArabicFile;
        if (f.format !== 'mushaf-arabic' || typeof f.ayahs !== 'object') throw new Error('format');
        this.loaded = f;
        return f;
      })
      .catch(() => {
        this.file = null; // retry on the next request (e.g. after coming back online)
        return null;
      });
    return this.file;
  }
}
